require_once __DIR__.'/config.php';require_role(['admin']);$rows=$db->query('SELECT username,action,entity_type,entity_id,details,ip_address,created_at FROM audit_logs ORDER BY id DESC LIMIT 500');page_header('Audit logs');echo '<h1>Audit trail</h1><div class="card"><p class="muted">Latest 500 events.</p><div class="table-wrap"><table><tr><th>Date/time</th><th>User</th><th>Action</th><th>Entity</th><th>Details</th><th>IP</th></tr>';while($r=$rows->fetch_assoc())echo '<tr><td>'.h($r['created_at']).'</td><td>'.h($r['username']).'</td><td>'.h($r['action']).'</td><td>'.h($r['entity_type'].' #'.$r['entity_id']).'</td><td>'.h($r['details']).'</td><td>'.h($r['ip_address']).'</td></tr>';echo '</table></div></div>';page_footer();